import{_ as t,o as e,c as o,a0 as a}from"./chunks/framework.BsWcg17L.js";const f=JSON.parse('{"title":"MPC simulation framework with process monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),n={name:"intro.md"};function r(s,i,l,d,c,m){return e(),o("div",null,[...i[0]||(i[0]=[a('<h1 id="mpc-simulation-framework-with-process-monitoring" tabindex="-1">MPC simulation framework with process monitoring <a class="header-anchor" href="#mpc-simulation-framework-with-process-monitoring" aria-label="Permalink to &quot;MPC simulation framework with process monitoring&quot;">​</a></h1><p>A simulation framework combining <strong>Model Predictive Control (MPC)</strong> with <strong>Principal Component Analysis (PCA)-based statistical process monitoring</strong> for fault detection and diagnosis in a multivariable dynamic system. Additional examples of <strong>Infinite-Horizon Robust Model Predictive Control</strong> and <strong>Partial Least Squares Regression (PLSR) Soft Sensor</strong>. The controller and monitoring combination is best suited for fixed point operations where MPC steers the system to one steady-state which is treated as &#39;normal operating conditions&#39; for which variance and covariance based multivariable calibration/monitoring/fault-detection methods namely PCA and PLS can be constructed.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This project demonstrates:</p><ul><li>Three different formulations of constrained MPC: <ul><li>Finite-Horizon constrained MPC solved with different QP solvers (Hildreth, Projected gradient descent, Primal-dual interior point and Active set method)</li><li>Offset-free MPC w/ Kalman Filter</li><li>Infinite-Horizon constrained MPC formulated as a Linear Matrix Inequality (LMI) and solved as a Semidefinite Program (SDP)</li></ul></li><li>Kalman Filter and partial state observations</li><li>PCA-based multivariate process monitoring <ul><li>Fault detection using T² and Q statistics and biplot</li><li>Fault diagnosis via contribution plots</li></ul></li><li>PLSR-based Soft Sensor <ul><li>T² and Q statistics and biplot</li></ul></li><li>Open-loop subspace identification: <ul><li>MOESP</li><li>N4SID</li></ul></li></ul><hr>',7)])])}const p=t(n,[["render",r]]);export{f as __pageData,p as default};
